}

public class Decodelong {

    public static long decodelong(byte llsb, byte lmlsb, byte lmmsb, byte lgsb, byte glsb, byte gmlsb, byte gmmsb,
                                  byte gmsb) {
        return  (llsb   & 0xFFL) |
                ((lmlsb & 0xFFL) << 8) |
                ((lmmsb & 0xFFL) << 16) |
                ((lgsb  & 0xFFL) << 24) |
                ((glsb  & 0xFFL) << 32) |
                ((gmlsb & 0xFFL) << 40) |
                ((gmmsb & 0xFFL) << 48) |
                (((long)gmsb) << 56);
}

public class Getvaluetypescodebybitmask {

    public byte getvaluetypescodebybitmask(boolean hasCh1, boolean hasCh2, boolean hasCh3, boolean hasCh4) {
		byte code = 0;

		if (hasCh1)
			code |= 0x8;
		if (hasCh2)
			code |= 0x4;
		if (hasCh3)
			code |= 0x2;
		if (hasCh4)
			code |= 0x1;

		return code;
}

public class Countchannelsinbitmask {

    public int countchannelsinbitmask(byte channelBitmask) {
		int temp = channelBitmask; 
		int result = 0; 
		while (temp > 0) { 
			result += temp & 0x01; 
			temp = temp >> 1;
}

