public class Rotleft15bit {

    public int rotleft15bit(int val, int rotate) {
    val = val &0x7FFF;

    for(; rotate > 0; rotate--) 
    {
      if((val & 0x4000) != 0) 
      {
        val = ((val << 1) & 0x7FFF) + 1;
}

