public class Computefieldofview {

    public double computefieldofview(double size, double distance) {
	    double radtheta;
	    double degtheta; 
	    radtheta = 2.0 * Math.atan2(size/2.0, distance);
	    degtheta = (180.0 * radtheta) / Math.PI;
	    return degtheta;
}

