public class Calculatedistance {

    public double calculatedistance(int x1, int y1, int z1, int x2, int y2, int z2, boolean includeZAxis) {
		double dx = (double) x1 - x2;
		double dy = (double) y1 - y2;

		if (includeZAxis)
		{
			double dz = z1 - z2;
			return Math.sqrt(dx * dx + dy * dy + dz * dz);
}

public class Roundto {

    public float roundto(float number, int numPlaces) {
		if (numPlaces <= 1)
			return Math.round(number);

		float exponent = (float) Math.pow(10, numPlaces);

		return Math.round(number * exponent) / exponent;
}

