public class Ease {

    public float ease(float start, float target) {
		if (Math.abs(target - start) < 4)
			return target;

		if (target < start)
			return start - 2;

		return start + 2;
}

public class Rolldice {

    public int rolldice(int sides, int count) {
		int value = 0;
		while (count-- > 0)
		{
			value += (int) (Math.random() * sides) + 1;
}

public class Dehexchar {

    public int dehexchar(char c) {
        if (c >= '0' && c <= '9') {
            return c - '0';
}

public class Calculatehorizontalmargin {

    public int calculatehorizontalmargin( int prevMarginRight, int marginLeft ) {
        int max = Math.max( prevMarginRight, marginLeft );
        int sum = prevMarginRight + marginLeft;
        if( sum < max ) {
            max += ( sum - max );
}

public class Calculateverticalmargin {

    public int calculateverticalmargin( int prevMarginBottom, int marginTop ) {
        int max = Math.max( prevMarginBottom, marginTop );
        int sum = prevMarginBottom + marginTop;
        if( sum < max ) {
            max += ( sum - max );
}

