public class Issupplemental {

    public boolean issupplemental(int c) {
        return (c >= 0x10000 && c <= 0x10FFFF);
}

public class Supplemental {

    public int supplemental(char h, char l) {
        return (h - 0xD800) * 0x400 + (l - 0xDC00) + 0x10000;
}

public class Highsurrogate {

    public char highsurrogate(int c) {
        return (char) (((c - 0x00010000) >> 10) + 0xD800);
}

public class Lowsurrogate {

    public char lowsurrogate(int c) {
        return (char) (((c - 0x00010000) & 0x3FF) + 0xDC00);
}

public class Ishighsurrogate {

    public boolean ishighsurrogate(int c) {
        return (0xD800 <= c && c <= 0xDBFF);
}

public class Islowsurrogate {

    public boolean islowsurrogate(int c) {
        return (0xDC00 <= c && c <= 0xDFFF);
}

public class Ismarkup {

    public boolean ismarkup(int c) {
        return c == '<' || c == '&' || c == '%';
}

public class Islastiteration {

    public boolean islastiteration(int idx, int maxIdx) {
        return idx == maxIdx - 1;
}

public class Isantepenultiemiteration {

    public boolean isantepenultiemiteration(int idx, int maxIdx) {
        return idx == maxIdx - 2;
}

public class Min {

    public int min(int a, int b) {
        return (a > b) ? b : a;
}

