    public int calculatethreshold(int newCapacity, float factor) {
		return (int) (newCapacity * factor);
}

public class Hashindex {

    public int hashindex(int hashCode, int dataSize) {
		return hashCode & (dataSize - 1);
}

public class Hash {

    public int hash(int h) {
        // Spread bits to regularize both segment and index locations,
        // using variant of single-word Wang/Jenkins hash.
        h += (h <<  15) ^ 0xffffcd7d;
        h ^= (h >>> 10);
        h += (h <<   3);
        h ^= (h >>>  6);
        h += (h <<   2) + (h << 14);
        return h ^ (h >>> 16);
}

public class Unsignedmod {

    public int unsignedmod(long unsignedLong, int signedModulus) {
        return (int) (unsignedLong & (((long) signedModulus) - 1));
}

public class Rotl {

    public int rotl(int x, int y) {
        return (x << y) | (x >>> -y);
}

public class Converthexdigit {

    public byte converthexdigit(byte b) {
        if ((b >= '0') && (b <= '9')) {
            return (byte) (b - '0');
}

